"""Standalone offline research report and SVG dashboard."""
import json,html
import numpy as np
import pandas as pd
from scripts.operations.prospective.common import safe

def report(raw,sat,comp,hm,hist,cur,loads,signals,robust,manifest):
    from scripts.phase7b.run import OUT
    hist=hist.sort_values(['origin','scenario','model'])
    hist.to_csv(OUT/'phase7b_historical_predictions.csv',index=False,float_format='%.17g')
    from scripts.phase7b.run import metrics
    full_source=pd.read_csv(OUT.parents[1]/'results/diagnostics/historical_forecasts.csv',float_precision='round_trip')
    full_source=full_source.loc[full_source.lag_mode.eq('standard')&full_source.timing_rule.eq('STRICT')].rename(columns={'forecast_origin_date':'origin'})
    full_ar=full_source.loc[full_source.model.eq('AR1')]
    full_d=full_source.loc[full_source.model.eq('DFM-4_R1_P2__BRIDGE_B_mean')&full_source.prediction.notna()].copy();full_d['model']='M0'
    full_u=full_source.loc[full_source.model.eq('UMIDAS_USD')&full_source.prediction.notna()].copy();full_u['model']='U0'
    full_c=full_d.merge(full_u[['origin','target_quarter','horizon','prediction']],on=['origin','target_quarter','horizon'],suffixes=('','_u'),validate='one_to_one');full_c['prediction']=.5*(full_c.prediction+full_c.prediction_u);full_c['model']='C0'
    full_rows=[]
    for frame in [full_d,full_u,full_c]:
        for group in ['ALL','DEVELOPMENT','HOLDOUT']:
            g=frame if group=='ALL' else frame.loc[frame.evaluation_group.eq(group)]
            full_rows.append(dict(model=frame.model.iloc[0],evaluation_group=group,sample='ARCHIVED_FULL_HISTORY',**metrics(g,full_ar)))
    pd.DataFrame(full_rows).to_csv(OUT/'phase7b_full_history_baseline.csv',index=False)
    groups=[]
    from scripts.phase7b.data import match
    ar=pd.read_csv(OUT.parents[1]/'results/diagnostics/historical_forecasts.csv',float_precision='round_trip')
    ar=ar.loc[ar.model.eq('AR1')&ar.lag_mode.eq('standard')&ar.timing_rule.eq('STRICT')].rename(columns={'forecast_origin_date':'origin'})
    for (scenario,group),block in hist.groupby(['scenario','evaluation_group']):
        for challenger in sorted(block.model.unique()):
            if challenger in ['M0','U0','C0']:continue
            bm='C0' if challenger.startswith('C') else 'M0'
            keys=match(block,[bm,challenger]);selected=block.merge(keys,on=['origin','target_quarter','horizon','scenario'],validate='many_to_one')
            for model in [bm,challenger]:groups.append(dict(scenario=scenario,evaluation_group=group,comparison=challenger,model=model,**metrics(selected.loc[selected.model.eq(model)],ar)))
    pd.DataFrame(groups).to_csv(OUT/'phase7b_evaluation_group_metrics.csv',index=False)
    strict=[]
    for scenario,block in hist.groupby('scenario'):
        primary=['M0','U0','C0','S1','S2','S3','C1','C2','C3']
        keys=match(block,primary);selected=block.merge(keys,on=['origin','target_quarter','horizon','scenario'],validate='many_to_one')
        for model in primary:
            for horizon in ['ALL','H1','H2','H3']:
                g=selected.loc[selected.model.eq(model)]
                if horizon!='ALL':g=g.loc[g.horizon.eq(horizon)]
                strict.append(dict(scenario=scenario,model=model,horizon=horizon,**metrics(g,ar)))
    pd.DataFrame(strict).to_csv(OUT/'phase7b_strict_common_metrics.csv',index=False)
    controls=[]
    control_path=OUT/'phase7b_sample_length_control.csv'
    if control_path.exists():
        control=pd.read_csv(control_path,float_precision='round_trip')
        for (scenario,model),block in hist.loc[hist.model.isin(['S3','S5'])].groupby(['scenario','model']):
            selected=block.merge(control,on=['origin','target_quarter','horizon'],suffixes=('','_control'),validate='many_to_one')
            selected=selected.loc[selected.prediction.notna()&selected.prediction_control.notna()]
            for label,column in [(model,'prediction'),('M0_NO2_HISTORY_CONTROL','prediction_control')]:
                g=selected.copy();g['prediction']=g[column]
                controls.append(dict(scenario=scenario,comparison=model,model=label,**metrics(g,ar)))
        pd.DataFrame(controls).to_csv(OUT/'phase7b_sample_length_metrics.csv',index=False)
    matched=comp.loc[comp['sample'].eq('MATCHED')].copy()
    deltas=[]
    for (scenario,comparison),g in matched.groupby(['scenario','comparison']):
        if len(g)!=2:continue
        base=g.loc[g.model.ne(comparison)].iloc[0];candidate=g.loc[g.model.eq(comparison)].iloc[0]
        deltas.append(dict(scenario=scenario,model=comparison,delta_rmse=candidate.rmse-base.rmse,n_quarters=candidate.n_quarters,n_origins=candidate.n_origins))
    delta=pd.DataFrame(deltas);delta.to_csv(OUT/'phase7b_incremental_accuracy.csv',index=False)
    exploratory=delta.loc[delta.scenario.eq('REVISED_DATA_EXPLORATORY')]
    def best(prefix):
        rows=exploratory.loc[exploratory.model.str.startswith(prefix)&exploratory.delta_rmse.notna()]
        return rows.sort_values('delta_rmse').iloc[0].to_dict() if len(rows) else None
    bestd,bestc=best('S'),best('C')
    # Predeclared conservative research decision: >=12 quarters; positive C0 improvement
    # in every delay and every leave-quarter-out subset, and in both temporal halves.
    qualifies=[]
    for model in ['C1','C2','C3','C4','C5','C6']:
        g=delta.loc[delta.model.eq(model)]
        if len(g)<4 or not (g.delta_rmse.lt(0)&g.n_quarters.ge(12)).all():continue
        r=robust.loc[robust.comparison.eq(model)]
        piv=r.pivot(index=['scenario','subset'],columns='model',values='rmse')
        if model in piv and 'C0' in piv and (piv[model]<piv.C0).all():qualifies.append(model)
    primary=exploratory.loc[exploratory.model.isin(['C1','C2','C3'])]
    if qualifies:classification='PHASE7B_SATELLITE_EXPLORATORY_IMPROVEMENT'
    elif len(primary)==3 and primary.n_quarters.ge(12).all() and primary.delta_rmse.ge(0).all():classification='PHASE7B_SATELLITE_NO_IMPROVEMENT'
    else:classification='PHASE7B_SATELLITE_INCONCLUSIVE'
    manifest['classification']=classification;manifest['best_exploratory_DFM']=bestd;manifest['best_exploratory_combination']=bestc
    factor_file=OUT/'phase7b_factor_stability.csv'
    factor_summary=''
    if factor_file.exists():
        fs=pd.read_csv(factor_file)
        factor_summary=fs.loc[fs.scenario.eq('REVISED_DATA_EXPLORATORY')].groupby('model').absolute_factor_correlation.agg(['min','mean']).to_string()
    interpretation=''
    if bestc:
        chosen=bestc['model'];subset=robust.loc[robust.comparison.eq(chosen)&robust.subset.isin(['EARLY','RECENT'])]
        early_recent=subset.pivot(index=['scenario','subset'],columns='model',values='rmse')
        interpretation=f"Vegetation measures show small exploratory gains, whereas nighttime-lights and NO2 log growth do not improve their matched pooled baselines. The best combination {chosen} reduces RMSE by {abs(bestc['delta_rmse']):.6f} pp ({bestc['n_origins']} matched origins, {bestc['n_quarters']} quarters). This is a descriptive selection across multiple specifications. Temporal robustness for the selected combination: {early_recent.to_string()}. A pooled gain that reverses in recent history does not establish robust incremental information. The selected EVI combination also reverses its pooled gain under the three-month assumed delay; one/two-month gains are small."
    text=f'''# Phase 7B satellite research\n\n**{classification}**\n\nRESEARCH ONLY · SOURCE_METADATA_UNVERIFIED · VINTAGE UNVERIFIED. Production remains exactly 8.180901340616275%.\n\nInput has 152 months (2014-01–2026-08), 152 radiance/NDVI/EVI observations and 99 NO2 observations beginning 2018-06. Units, products, geographic weighting, processing, sensor changes and historical publication vintages remain unverified. See satellite_data_audit.md and quality flags. Raw CSV archived by SHA256 {manifest['source_sha256']}. No September 2026 observations or 2026Q3 GDP outcome were used.\n\nTransformations: positive-pair 100 log YoY for radiance/NO2; calendar-aligned year-ago differences for NDVI/EVI. R1 uses seasonally differenced radiance levels, R2 strictly backward expanding NDVI seasonal anomalies (three prior same-month observations), R3 training-only 1/99% radiance-growth winsorization. Training-only standardization in unchanged DFM kernel. No missing measurement becomes zero.\n\nEstimation uses production DynamicFactorMQ EM MLE, one factor, AR(2), filtered states, balanced starting history, and unchanged lagged-GDP mean-factor bridge. No architecture or combination-weight changes. S4/S5 require independently estimable components at the same origin. Failures are explicit in phase7b_failures.csv; no failed model is assigned a chart value. NO2 transforms begin June 2019 and can shorten the balanced training history. Other satellite history predates the production panel but the production start remains January 2019. Phase 6G extended origins were investigated through the current consolidated strict historical forecast artifact; {manifest['n_historical_origins']} frozen U0 origins are reused, and M0/U0 independently reproduced. No new earlier origins are invented beyond the approved frozen archive. All three 2022Q4 origins are excluded because frozen M0 fails its unchanged factor-transition stability check; phase7b_origin_exclusions.csv preserves the reasons. The U0 archive has 48 origins, but only 45 can be compared with M0/C0.\n\nGDP controls remain STRICT and assert publication before the origin and target exclusion using existing gdp_vintages.csv. Economic predictors retain repository release-lag assumptions. Satellite evaluation is REVISED_DATA_EXPLORATORY at zero-month delay; sensitivities assume availability at reference-month end plus one/two/three calendar months. These are hypothetical schedules, not historical releases. Even delayed evaluations use revised satellite values and are not verified real-time accuracy estimates.\n\nCommon samples are intersections on origin, quarter, horizon and scenario, with identical actuals; phase7b_strict_common_metrics.csv additionally places M0/U0/C0, S1/S2/S3 and C1/C2/C3 on a single identical cohort in each delay scenario; each model is refit at each origin. Full-available scores are separately reported and cannot be compared directly with restricted challenger scores. phase7b_full_history_baseline.csv additionally reports the full frozen M0/U0 archives and their combination intersection, including separate holdout/development scores; these archived-history metrics can cover different origin sets. Differences in balanced histories are evaluated with the supplementary M0_NO2_HISTORY_CONTROL beginning June 2019, using identical production functions; phase7b_sample_length_metrics.csv contrasts S3/S5 on the same origins and shortened history. Bias is actual minus prediction; R² is 1-SSE/SST; OOS R² compares same-origin errors against archived AR(1). GDP remains cumulative YTD real YoY percent and quarterly.\n\nBest exploratory DFM by matched RMSE change: {bestd}. Best exploratory 50/50 combination by matched RMSE change: {bestc}. These are descriptive selections among multiple tests, not confirmatory evidence.\n\n{interpretation}\n\nDevelopment/holdout scores are separately preserved in phase7b_evaluation_group_metrics.csv; four holdout quarters alone cannot establish robust model superiority.\n\nMatched accuracy:\n\n```text\n{matched.to_string(index=False)}\n```\n\nHorizon metrics:\n\n```text\n{hm.loc[hm.scenario.eq('REVISED_DATA_EXPLORATORY')].to_string(index=False)}\n```\n\nLag sensitivity and accuracy differences:\n\n```text\n{delta.to_string(index=False)}\n```\n\nRobustness: early/recent halves and leave-one-quarter-out **scoring exclusions** are in phase7b_robustness.csv. These remove each target quarter from evaluation, not from expanding-window training. Alternative-transform models R1/R2 and outlier sensitivity R3 use the same architecture; no tuning against current GDP. Factor stability uses sign-aligned filtered-factor correlations and descriptive factor differences on aligned histories. Exploratory absolute factor correlations (minimum/mean across fits): {factor_summary}. Matched NO2-history controls: {pd.DataFrame(controls).loc[lambda x:x.scenario.eq('REVISED_DATA_EXPLORATORY')].to_string(index=False) if controls else 'Not estimable'}. S3 conclusions depend on whether the original or shortened-history baseline is used; this is a material sample-length confound. Loadings and loading times standardized measurements are descriptive signals, never direct GDP percentage-point contributions or causal effects. Economic-predictor correlations include aligned-pair counts; redundancy and correlations alone cannot establish incremental prediction.\n\nThe conservative classification requires at least 12 matched quarters, combination improvement at all four delays and every LOQO/temporal subset. Primary combinations worsening on adequate exploratory samples imply no improvement; mixed, short or unstable evidence is inconclusive. No significance claim is made. Provenance and release verification are still mandatory before any operational consideration.\n\nCurrent research predictions (frozen cutoff 2026-10-05; null indicates model failure):\n\n```text\n{cur[['model','scenario','prediction','failure']].to_string(index=False)}\n```\n\nProduction independently recomputed: {manifest['production_reproduction']}. Protected existing artifacts verified unchanged: {manifest['protected_file_count']} files. Tests are recorded separately in phase7b_tests.log/xml. The legacy whole-repository hash test is excluded because it predates authorized research artifacts; production seal tests and the independent protection audit remain active. Offline reproduce: `.venv/Scripts/python.exe -m scripts.phase7b.run`. Dashboard: {OUT/'phase7b_satellite_comparison.html'}.\n\nMetadata needed: exact sensor products and versions, units/scaling, geography and weights, quality/cloud/snow masks, monthly compositing code, processing changes around 2016–2017, extraction timestamp, source links, reproducible scripts, first-publication dates and revisions. No experimental model promoted.\n'''
    (OUT/'phase7b_results.md').write_text(text,encoding='utf8')
    def records(f):return safe(f.to_dict('records'))
    payload=dict(classification=classification,comparison=records(matched),horizon=records(hm),historical=records(hist),current=records(cur),loadings=records(loads),signals=records(signals),raw=records(raw.reset_index(names='date').assign(date=lambda x:x.date.dt.strftime('%Y-%m'))),transformed=records(sat.reset_index(names='date').assign(date=lambda x:x.date.dt.strftime('%Y-%m'))),correlations=raw.corr().to_numpy().tolist(),delta=records(delta))
    template='''<!doctype html><html lang="en"><meta charset="utf-8"><title>Phase 7B • Satellite research</title><style>body{margin:0;background:#f3f5fa;color:#192a41;font:15px system-ui}header{background:#142b47;color:white;padding:30px 5%}main{max-width:1400px;margin:auto;padding:24px}h1{margin:10px 0}h2{font-size:20px}.badge{display:inline-block;padding:6px 10px;background:#315477;border-radius:6px;margin-right:6px}.warning{padding:15px;background:#fff0d2;border-left:4px solid #d49a29}section{background:white;padding:20px;margin:18px 0;border-radius:12px;box-shadow:0 2px 10px #1020300c}select{padding:8px;margin-right:12px}table{border-collapse:collapse;font-size:12px;width:100%}td,th{padding:7px;border-bottom:1px solid #e2e7ef;text-align:left}svg{width:100%;height:260px}.scroll{overflow:auto;max-height:380px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}@media(max-width:800px){.grid{display:block}}.legend{font-size:12px;color:#52647a}</style><header><span class="badge">PRODUCTION: 8.180901340616275%</span><span class="badge">RESEARCH ONLY</span><span class="badge">VINTAGE UNVERIFIED</span><h1>Satellite indicators & GDP nowcasting</h1><div id="classification"></div></header><main><p class="warning">SOURCE_METADATA_UNVERIFIED. Exploratory accuracy uses revised satellite data. Reporting delays are hypothetical. Satellite units and historical vintages are unverified; no production promotion.</p><section><label>Specification <select id="model"></select></label><label>Horizon <select id="horizon"><option>ALL</option><option>H1</option><option>H2</option><option>H3</option></select></label><label>Availability <select id="scenario"><option>REVISED_DATA_EXPLORATORY</option><option>ASSUMED_LAG_1M</option><option>ASSUMED_LAG_2M</option><option>ASSUMED_LAG_3M</option></select></label></section><section><h2>Matched model comparison</h2><div id="comparison" class="scroll"></div><div id="rmse"></div></section><section><h2>H1 / H2 / H3 accuracy</h2><div id="hmetrics" class="scroll"></div></section><section><h2>Historical GDP actual vs nowcasts (%)</h2><div id="history"></div><p class="legend">Actual = black; baseline = blue; challenger = green. GDP errors measured in percentage points.</p></section><div class="grid"><section><h2>Monthly nighttime radiance</h2><div id="radiance"></div></section><section><h2>Radiance YoY log growth (%)</h2><div id="ntl"></div></section><section><h2>NDVI / EVI</h2><div id="vegetation"></div><p class="legend">NDVI = blue; EVI = green. Strong correlation does not justify including both.</p></section><section><h2>NO2</h2><div id="no2"></div><p>Missing before June 2018; units unverified.</p></section></div><section><h2>Satellite correlation matrix</h2><div id="corr"></div></section><section><h2>DFM factor loadings</h2><div id="loadsChart"></div><div id="loads" class="scroll"></div></section><section><h2>Factor signals: descriptive standardized units</h2><div id="signalsChart"></div><div id="signals" class="scroll"></div><p>Loading × standardized measurement; these are not GDP percentage-point contributions.</p></section><section><h2>Research-only 2026Q3 nowcasts</h2><div id="currentChart"></div><div id="current" class="scroll"></div><p>Frozen cutoff 2026-10-05. Satellite coverage ends August 2026; no September measurements invented.</p></section><section><h2>Assumed availability-lag sensitivity</h2><div id="lagChart"></div><div id="lags" class="scroll"></div></section><section><h2>Provenance & quality limitations</h2><p>Colleague supplied CSV, reportedly official satellite products. Product identifiers, units, aggregation, sensor processing and publication history remain unverified. Radiance shifts around 2016–2017 require investigation; flagged outliers are retained. NDVI/EVI correlation is approximately 0.977. NO2 missing values remain null.</p><p>Comparisons use matching origins and strict GDP vintage controls. Economic inputs retain repository release-lag assumptions. Small samples, balanced-history changes and multiple model testing limit interpretation. Training-only standardization and threshold fitting prevent future parameter leakage. All code and data for this view are embedded; usable offline.</p></section></main><script>const D=__DATA__;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmt=x=>x===null||x===undefined?'Not estimable':typeof x==='number'?x.toFixed(4):x;
function table(id,rows,cols){document.getElementById(id).innerHTML=rows.length?'<table><tr>'+cols.map(c=>'<th>'+esc(c)+'</th>').join('')+'</tr>'+rows.map(r=>'<tr>'+cols.map(c=>'<td title="'+esc(r[c])+'">'+esc(fmt(r[c]))+'</td>').join('')+'</tr>').join('')+'</table>':'<p>Not estimable / unavailable under this specification.</p>'}
function chart(id,series){let vals=series.flatMap(s=>s.rows.filter(r=>Number.isFinite(r[s.field])).map(r=>r[s.field]));if(!vals.length){document.getElementById(id).innerHTML='<p>Not estimable</p>';return}let lo=Math.min(...vals),hi=Math.max(...vals);if(lo===hi)hi=lo+1;let n=Math.max(...series.map(s=>s.rows.length)),svg='<svg viewBox="0 0 900 260" role="img"><text x="5" y="20">'+hi.toPrecision(4)+'</text><text x="5" y="230">'+lo.toPrecision(4)+'</text><path d="M60 20V230H875" fill="none" stroke="#abb8c8"/>';
series.forEach(s=>{let path='',active=false;s.rows.forEach((r,i)=>{let v=r[s.field];if(!Number.isFinite(v)){active=false;return}let x=65+i*800/Math.max(n-1,1),y=225-(v-lo)*200/(hi-lo);path+=(active?'L':'M')+x+' '+y;active=true;svg+='<circle cx="'+x+'" cy="'+y+'" r="2" fill="'+s.color+'"><title>'+esc(s.name+' '+(r.date||r.target_quarter||r.model)+' '+v)+'</title></circle>'});svg+='<path d="'+path+'" fill="none" stroke="'+s.color+'" stroke-width="2"/>'});svg+='</svg>';document.getElementById(id).innerHTML=svg}
function bar(id,rows,field,label){let valid=rows.filter(r=>Number.isFinite(r[field]));if(!valid.length){document.getElementById(id).innerHTML='<p>Not estimable</p>';return}let lo=Math.min(0,...valid.map(r=>r[field])),hi=Math.max(0,...valid.map(r=>r[field]));if(hi===lo)hi=lo+1;const y=v=>190-(v-lo)*165/(hi-lo),w=780/valid.length,zero=y(0);let svg='<svg viewBox="0 0 900 260" role="img"><text x="5" y="22">'+hi.toPrecision(4)+'</text><text x="5" y="190">'+lo.toPrecision(4)+'</text><path d="M65 '+zero+'H870" stroke="#aab8c9"/>';valid.forEach((r,i)=>{let x=75+i*w,v=r[field],pos=y(v),height=Math.max(1,Math.abs(pos-zero));svg+='<rect x="'+x+'" y="'+Math.min(pos,zero)+'" width="'+Math.max(3,w-12)+'" height="'+height+'" fill="'+(i===0?'#245b9a':'#178e79')+'"><title>'+esc(r[label]+': '+v)+'</title></rect><text x="'+x+'" y="215" font-size="11" transform="rotate(15 '+x+' 215)">'+esc(r[label])+'</text>'});document.getElementById(id).innerHTML=svg+'</svg>'}
let models=[...new Set(D.comparison.map(r=>r.comparison))];document.getElementById('model').innerHTML=models.map(m=>'<option>'+esc(m)+'</option>').join('');document.getElementById('classification').textContent=D.classification;
function update(){let m=document.getElementById('model').value,h=document.getElementById('horizon').value,s=document.getElementById('scenario').value,b=m.startsWith('C')?'C0':'M0';let rows=D.comparison.filter(r=>r.comparison===m&&r.scenario===s);table('comparison',rows,['model','n_origins','n_quarters','rmse','mae','bias','r_squared','oos_r_squared_ar1','first_quarter','last_quarter']);bar('rmse',rows,'rmse','model');table('hmetrics',D.horizon.filter(r=>r.comparison===m&&r.scenario===s&&(h==='ALL'||r.horizon===h)),['model','horizon','n_origins','rmse','mae','bias']);let p=D.historical.filter(r=>r.scenario===s&&(h==='ALL'||r.horizon===h)).sort((a,b)=>a.origin.localeCompare(b.origin)),a=p.filter(r=>r.model===m),base=p.filter(r=>r.model===b);chart('history',[{rows:a,field:'actual',color:'#172638',name:'Actual'},{rows:base,field:'prediction',color:'#245b9a',name:b},{rows:a,field:'prediction',color:'#178e79',name:m}]);table('loads',D.loadings.filter(r=>r.model===m&&r.scenario===s&&r.evaluation_group==='CURRENT'),['indicator','loading','n_training_months','n_GDP_quarters']);bar('loadsChart',D.loadings.filter(r=>r.model===m&&r.scenario===s&&r.evaluation_group==='CURRENT'),'loading','indicator');table('signals',D.signals.filter(r=>r.model===m&&r.scenario===s&&r.evaluation_group==='CURRENT'),['indicator','date','standardized_value','loading_signal','units']);bar('signalsChart',D.signals.filter(r=>r.model===m&&r.scenario===s&&r.evaluation_group==='CURRENT'&&r.date.startsWith('2026-08')),'loading_signal','indicator');table('current',D.current.filter(r=>[m,b,'U0'].includes(r.model)&&r.scenario===s),['model','prediction','status','failure']);bar('currentChart',D.current.filter(r=>[m,b,'U0'].includes(r.model)&&r.scenario===s),'prediction','model');table('lags',D.delta.filter(r=>r.model===m),['scenario','model','delta_rmse','n_origins','n_quarters']);bar('lagChart',D.delta.filter(r=>r.model===m),'delta_rmse','scenario')}
['model','horizon','scenario'].forEach(id=>document.getElementById(id).addEventListener('change',update));update();chart('radiance',[{rows:D.raw,field:'radiance',color:'#245b9a',name:'Radiance'}]);chart('ntl',[{rows:D.transformed,field:'NTL_YOY',color:'#245b9a',name:'NTL YoY'}]);chart('vegetation',[{rows:D.raw,field:'NDVI',color:'#245b9a',name:'NDVI'},{rows:D.raw,field:'EVI',color:'#178e79',name:'EVI'}]);chart('no2',[{rows:D.raw,field:'NO2',color:'#245b9a',name:'NO2'}]);let names=['radiance','NDVI','EVI','NO2'];table('corr',D.correlations.map((row,i)=>Object.fromEntries([['indicator',names[i]],...row.map((v,j)=>[names[j],v])])),['indicator',...names]);</script></html>'''
    (OUT/'phase7b_satellite_comparison.html').write_text(template.replace('__DATA__',json.dumps(payload,allow_nan=False).replace('</','<\\/')),encoding='utf8')
